WHEN MATCHED THEN
    UPDATE SET 
        FullName = N'Trịnh Hùng Thắng',
        DepartmentId = ISNULL(NULL, target.DepartmentId),
        DepartmentCode = ISNULL(NULL, target.DepartmentCode),
        PositionId = ISNULL(NULL, target.PositionId),
        PositionGrade = N'Sr. Ms Tech',
        PositionRole = N'Sr. Ms Tech',
        BankName = ISNULL(N'VIETCOMBANK', target.BankName),
        BankAccountNumber = ISNULL(N'0121001687294', target.BankAccountNumber),
        JoinDate = ISNULL('2026-07-06', target.JoinDate),
        ContractEndDate = ISNULL('2026-09-06', target.ContractEndDate),
