WHEN NOT MATCHED THEN
    INSERT (UserId, UserCode, FullName, DepartmentId, DepartmentCode, PositionId, PositionGrade, PositionRole, Plant, VendorName, ContractType, JoinDate, ContractEndDate, BankName, BankAccountNumber, IsPregnant, HasYoungChild, Status, UseFlag, CreatedAt, CreatedBy)
